/bin/zsh -c "node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import { Schema, Either } from 'effect';
import { manifestSchema, importManifest } from './dist/index.js';
const parcel = { reference: ' A ', grams: 1e20, service: 'standard', extra: {} };
const input = { partner: ' Partner ', parcels: [parcel, { reference: ' B ', grams: 1, service: 'express' }], extra: {} };
const expected = { partner: 'Partner', parcels: [{ reference: 'A', grams: 1e20, service: 'standard' }, { reference: 'B', grams: 1, service: 'express' }] };
const result = importManifest(input);
assert.deepEqual(result, { ok: true, manifest: expected });
assert.deepEqual(Schema.decodeUnknownSync(manifestSchema)(input), expected);
assert.notEqual(result.manifest, input);
assert.notEqual(result.manifest.parcels, input.parcels);
assert.notEqual(result.manifest.parcels[0], parcel);
assert.equal(parcel.reference, ' A ');
const invalid = [undefined, null, false, 1, 'text', [], {}, { partner: ' ', parcels: [parcel] }, { partner: 'x', parcels: [] }, { partner: 'x', parcels: [parcel, parcel] }];
for (const grams of [undefined, null, '1', NaN, Infinity, -Infinity, 0, -1, 1.5]) invalid.push({ partner: 'x', parcels: [{ ...parcel, grams }] });
for (const reference of [undefined, null, 1, ' ']) invalid.push({ partner: 'x', parcels: [{ ...parcel, reference }] });
for (const service of [undefined, null, 1, 'overnight']) invalid.push({ partner: 'x', parcels: [{ ...parcel, service }] });
for (const value of invalid) {
  assert.deepEqual(importManifest(value), { ok: false, reason: 'invalid-manifest' });
  assert.ok(Either.isLeft(Schema.decodeUnknownEither(manifestSchema)(value)));
}
console.log('Direct decoder and importer checks passed: normalization, validation, order, and detached output.');
JS"

